mapper.select:
select setmeal.id, category_id, setmeal.name, price, setmeal.status, description, image, setmeal.update_time,
       category.name as category_name from setmeal,category

    category_id = category.id

        and category_id = #{categoryId}


        and name = #{name}


        and status = #{status}


order by setmeal.create_time desc
